function prepareGa4Report({ scheduledAt, propertyId, recipient, reportTimezone }) {
  if (
    !/^[1-9][0-9]{1,19}$/.test(propertyId) ||
    recipient.length > 180 ||
    !/^[^\s@,;<>]+@[^\s@,;<>]+\.[^\s@,;<>]+$/.test(recipient) ||
    /\.invalid$/i.test(recipient)
  ) {
    throw new Error("Set a GA4 property ID and one report recipient");
  }
  const instant = new Date(scheduledAt);
  if (!Number.isFinite(instant.getTime())) throw new Error("Expected a valid scheduled time");
  const local = new Intl.DateTimeFormat("en", {
    timeZone: reportTimezone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  });
  const day = Object.fromEntries(
    local.formatToParts(instant).map((part) => [part.type, part.value]),
  );
  const endDate = day.year + "-" + day.month + "-" + day.day;
  const toDate = (offset) =>
    new Date(Date.parse(endDate) - offset * 86400000).toISOString().slice(0, 10);
  const startDate = toDate(7);
  return {
    propertyId,
    recipient,
    reportTimezone,
    startDate,
    endDate,
    latestComplete: toDate(1),
    priorComplete: toDate(2),
    dateRanges: [{ startDate, endDate }],
    key: "ga4:" + propertyId + ":" + endDate + ":" + recipient.toLowerCase(),
  };
}
const settings = {
  propertyId: "YOUR_GA4_PROPERTY_ID",
  recipient: "reports@example.invalid",
  reportTimezone: "UTC",
};
return [{ json: prepareGa4Report({ ...settings, scheduledAt: $input.first().json.timestamp }) }];

function collectGa4Facts(report, settings) {
  const dimensions = report?.dimensionHeaders?.map((x) => x.name);
  const measures = report?.metricHeaders?.map((x) => x.name);
  const rows = report?.rows ?? [];
  const rowCount = report?.rowCount ?? 0;
  if (
    !dimensions ||
    dimensions.join(",") !== "date,sourceMedium" ||
    !measures ||
    measures.join(",") !== "sessions" ||
    report.metricHeaders[0].type !== "TYPE_INTEGER" ||
    (report?.metadata?.timeZone && report.metadata.timeZone !== settings.reportTimezone)
  ) {
    throw new Error("Unexpected GA4 report fields or property time zone");
  }
  if (
    !Array.isArray(rows) ||
    !Number.isSafeInteger(rowCount) ||
    rowCount !== rows.length ||
    rowCount > 5000
  ) {
    throw new Error("GA4 report was truncated or exceeded 5,000 rows");
  }
  const dimensionsSeen = new Set();
  const bySource = new Map();
  const byDay = new Map();
  let count = 0n;
  for (const row of rows) {
    const [compactDay, source] = row.dimensionValues?.map((x) => x.value) ?? [];
    const [value] = row.metricValues?.map((x) => x.value) ?? [];
    const date =
      /^\d{8}$/.test(compactDay ?? "") && compactDay.replace(/^(....)(..)(..)$/, "$1-$2-$3");
    const dateValue = date && new Date(date + "T00:00:00Z");
    const validDate =
      dateValue &&
      Number.isFinite(dateValue.getTime()) &&
      dateValue.toISOString().slice(0, 10) === date;
    const key = compactDay + "\n" + source;
    if (
      !validDate ||
      date < settings.startDate ||
      date > settings.endDate ||
      dimensionsSeen.has(key) ||
      row.dimensionValues.length !== 2 ||
      typeof source !== "string" ||
      !source ||
      source.length > 300 ||
      /[\x00-\x1f\x7f]/.test(source) ||
      typeof value !== "string" ||
      !/^\d{1,20}$/.test(value) ||
      row.metricValues.length !== 1
    ) {
      throw new Error("GA4 returned an invalid, repeated, or out-of-period report row");
    }
    dimensionsSeen.add(key);
    const sessions = BigInt(value);
    count += sessions;
    byDay.set(date, (byDay.get(date) ?? 0n) + sessions);
    bySource.set(source, (bySource.get(source) ?? 0n) + sessions);
  }
  const leaders = [...bySource]
    .sort(([an, a], [bn, b]) => (a === b ? (an < bn ? -1 : 1) : a > b ? -1 : 1))
    .slice(0, 3)
    .map(([source, sessions]) => ({ source, sessions: String(sessions) }));
  const latest = byDay.get(settings.latestComplete);
  const prior = byDay.get(settings.priorComplete);
  const comparison =
    latest === undefined || prior === undefined
      ? null
      : {
          latest: { date: settings.latestComplete, sessions: String(latest) },
          prior: { date: settings.priorComplete, sessions: String(prior) },
          direction: latest === prior ? "unchanged" : latest > prior ? "up" : "down",
        };
  const notices = [];
  if (report.metadata?.subjectToThresholding) notices.push("GA4 applied or may apply thresholds.");
  if (report.metadata?.dataLossFromOtherRow) notices.push("GA4 combined some rows into (other).");
  if (report.metadata?.samplingMetadatas?.length) notices.push("GA4 reported sampling.");
  return {
    startDate: settings.startDate,
    endDate: settings.endDate,
    reportTimezone: settings.reportTimezone,
    count: String(count),
    rowCount,
    leaders,
    comparison,
    notices,
  };
}
return [
  { json: collectGa4Facts($input.first().json, $("Set GA4 property and recipient").first().json) },
];

function writeGa4Email({ reply, facts }) {
  const messages = reply?.output?.filter((x) => x?.type === "message");
  const expected = messages?.[0];
  const content = expected?.content;
  if (
    reply?.status !== "completed" ||
    messages?.length !== 1 ||
    expected?.role !== "assistant" ||
    expected?.status !== "completed" ||
    content?.length !== 1 ||
    content[0]?.type !== "output_text"
  ) {
    throw new Error("OpenAI did not complete the executive summary selection");
  }
  const choices = JSON.parse(content[0].text);
  const actions = {
    compare:
      "Review the latest complete day against its predecessor to identify which channels contributed to the change.",
    tag: "Review campaign tagging for the listed sources and media before comparing channels.",
    coverage:
      "Check analytics collection and compare a complete reporting window before adjusting campaigns.",
  };
  if (
    !choices ||
    !["sources", "complete_days", "coverage"].includes(choices.focus) ||
    !Object.hasOwn(actions, choices.action) ||
    (choices.focus === "sources" && !facts.leaders.length) ||
    (choices.focus === "complete_days" && !facts.comparison) ||
    (choices.action === "compare" && !facts.comparison) ||
    (choices.action === "tag" && !facts.leaders.length)
  ) {
    throw new Error("OpenAI selected a summary that the report does not support");
  }
  const top = facts.leaders
    .map(({ source, sessions }) => source + ": " + sessions + " sessions")
    .join("\n");
  const comparison = facts.comparison;
  const daySummary = comparison
    ? comparison.latest.date +
      " (" +
      comparison.latest.sessions +
      ") vs " +
      comparison.prior.date +
      " (" +
      comparison.prior.sessions +
      "): " +
      comparison.direction +
      " in sessions."
    : "Two comparable complete days were unavailable.";
  const coverage = facts.rowCount
    ? "The end date may contain partial data."
    : "GA4 returned no rows for this window.";
  const emphasis = { sources: top, complete_days: daySummary, coverage };
  return {
    body: [
      "Overview\n" +
        facts.startDate +
        " through " +
        facts.endDate +
        " inclusive (" +
        facts.reportTimezone +
        "). " +
        coverage,
      "Key performance indicators\n" +
        facts.count +
        " sessions summed across " +
        facts.rowCount +
        " returned date/source-medium rows." +
        (top ? "\nTop sources / media:\n" + top : ""),
      "Trends and insights\n" +
        daySummary +
        (choices.focus === "complete_days" ? "" : "\n" + emphasis[choices.focus]),
      "Opportunities and recommendations\n" + actions[choices.action],
      "Conclusion\n" + (facts.notices.join(" ") || coverage),
    ].join("\n\n"),
  };
}

const config = $("Set GA4 property and recipient").first().json;
return [
  {
    json: {
      ...writeGa4Email({
        reply: $input.first().json,
        facts: $("Verify dates and count sessions").first().json,
      }),
      key: config.key,
      recipient: config.recipient,
    },
  },
];

const messageId = $input.first().json.id;
if (typeof messageId !== "string" || !messageId) throw new Error("Gmail did not confirm delivery");
return [{ json: { messageId } }];
